import React from "react";
import { COLORS } from "../constants.js";

export function FlagIcon({ flag, size = 15 }) {
  const width = Math.round(size * 1.4);
  return (
    <span
      style={{
        display: "inline-block",
        width: `${width}px`,
        height: `${size}px`,
        overflow: "hidden",
        borderRadius: "2px",
        verticalAlign: "middle",
        position: "relative",
        lineHeight: 1,
      }}
    >
      <span style={{ position: "absolute", top: "50%", left: "50%", fontSize: `${Math.round(size * 1.55)}px`, lineHeight: 1, transform: "translate(-50%, -50%)" }}>{flag}</span>
    </span>
  );
}

export function VerifiedBadge({ size = 18, title = "Lieu vérifié par un administrateur" }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" role="img" aria-label={title}>
      <title>{title}</title>
      <polygon
        points="12,1 14.51,2.63 17.5,2.47 18.86,5.14 21.53,6.5 21.37,9.49 23,12 21.37,14.51 21.53,17.5 18.86,18.86 17.5,21.53 14.51,21.37 12,23 9.49,21.37 6.5,21.53 5.14,18.86 2.47,17.5 2.63,14.51 1,12 2.63,9.49 2.47,6.5 5.14,5.14 6.5,2.47 9.49,2.63"
        fill={COLORS.amber}
      />
      <circle cx="12" cy="12" r="7.4" fill={COLORS.amberDark} />
      <path d="M8.3 12.3l2.4 2.4 5-5.4" fill="none" stroke={COLORS.paper} strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

